// 1. Obtenemos la lista de temas del nodo anterior
const topics = $input.first().json.topics;

// 2. Cuántos temas quieres seleccionar
const count = 4; 

// 3. Lógica para elegir al azar sin repetir (usando Math.random)
const selectedTopics = [];
const tempTopics = [...topics]; // Creamos una copia para ir sacando de ahí

// Mientras no hayamos juntado los 4 y sigan quedando temas:
while (selectedTopics.length < count && tempTopics.length > 0) {
  // Elegimos un índice al azar
  const randomIndex = Math.floor(Math.random() * tempTopics.length);

  // Agregamos el tema a nuestra lista final
  selectedTopics.push(tempTopics[randomIndex]);

  // Lo borramos de la lista temporal para que no salga repetido
  tempTopics.splice(randomIndex, 1);
}

// 4. Devolvemos el resultado limpio
return [{ 
  json: { 
    randomTopics: selectedTopics 
  } 
}];

